class Solution:
    def removeOnes(self, grid: List[List[int]]) -> bool:
        row0 = grid[0]
        for row in grid[1:]:
            flip = row[0] ^ row0[0]
            if any(v != (row0[j] ^ flip) for j, v in enumerate(row)):
                return False
        return True

