class Solution {
public:
    bool removeOnes(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        for (int i = 1; i < m; i++) {
            int flip = grid[i][0] ^ grid[0][0];
            for (int j = 0; j < n; j++)
                if (grid[i][j] != (grid[0][j] ^ flip)) return false;
        }
        return true;
    }
};

